/****************************************************************************
 * app/conv/conv_main.c
 *
 * Conversation history on the board: seed it, query it locally, ship the
 * matches to the web console.
 *
 * The point of running the query here rather than on the PC is that the
 * recordings are here.  Shipping every conversation to the web so it can
 * filter them would move megabytes to answer a question whose answer is a
 * few hundred bytes, over a link that also has to carry live audio.  The
 * board reads its own index -- one sequential pass over a few kilobytes --
 * and sends only what matched.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <errno.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "conv_send.h"
#include "conv_store.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* Buffer for one transcript or one analysis when printing a record. */

#define CONV_TEXT_MAX     1024

/****************************************************************************
 * Private Types
 ****************************************************************************/

/* What a seeded record is made of.  Held as data rather than built by code
 * so the set is easy to read and extend.
 *
 * day_offset is days before today, resolved against the date the caller
 * supplies -- the board has no clock, so "today" has to come from outside.
 */

struct conv_seed_s
{
  int day_offset;
  unsigned int hour;
  unsigned int minute;
  unsigned int duration_ms;
  const char *cue;
  const char *meaning;
  float confidence;
  bool unable_to_judge;
  const char *reason;
  const char *suggestion;
  const char *summary;
  const char *transcript;
};

/* Six conversations across a fortnight, so a date range has something to
 * include and something to exclude.
 *
 * The cue vocabulary and the hedged `meaning` wording follow social-cue/v1
 * as social_cue_skill.h defines it: "possible confusion", never "confused".
 * One record carries unable_to_judge, because a history that never contains
 * an inconclusive analysis would misrepresent what the model actually
 * returns, and the query has to cope with it.
 */

static const struct conv_seed_s g_seeds[] =
{
  {
    -13, 9, 42, 8000, "brow_furrow", "possible confusion", 0.72f, false,
    "", "slow down and check whether the last point landed",
    "周末爬山的安排",
    "对方: 周末那个爬山还去吗\n"
    "我: 去啊，几点集合\n"
    "对方: 早上六点，太早了点\n"
    "我: 六点可以，我定个闹钟\n"
    "对方: 那行，我到时候联系你\n"
  },
  {
    -9, 14, 5, 12000, "gaze_aversion", "possible discomfort", 0.64f, false,
    "", "give them room and avoid pressing the topic",
    "项目排期的分歧",
    "对方: 这个排期我觉得有点紧\n"
    "我: 哪一块最紧\n"
    "对方: 测试那块，只留了两天\n"
    "我: 那我们把测试挪到下周\n"
    "对方: 嗯，那样好一些\n"
    "我: 我今天改一下计划发你\n"
  },
  {
    -6, 10, 20, 6000, "smile", "possible agreement", 0.81f, false,
    "", "a good moment to confirm the next step",
    "确认了下周的评审时间",
    "对方: 下周三下午可以吗\n"
    "我: 可以，三点行不行\n"
    "对方: 三点没问题\n"
    "我: 那我发个日历邀请\n"
  },
  {
    -4, 16, 48, 15000, "head_shake", "possible disagreement", 0.69f, false,
    "", "ask what specifically does not work before restating",
    "关于爬山路线的不同意见",
    "对方: 我还是觉得走西边那条路线不合适\n"
    "我: 为什么呢\n"
    "对方: 那边石头多，下雨天滑\n"
    "我: 那我们走东边，虽然远一点\n"
    "对方: 远点没关系，安全重要\n"
  },
  {
    -2, 11, 15, 4000, "", "", 0.31f, true,
    "face partially out of frame", "reposition before judging",
    "画面不完整，未能判断",
    "对方: 那个东西你带了吗\n"
    "我: 带了，在包里\n"
  },
  {
    0, 15, 30, 9000, "lean_forward", "possible interest", 0.77f, false,
    "", "expand on the point that drew them in",
    "聊到爬山装备",
    "对方: 你那双鞋在哪买的\n"
    "我: 网上买的，牌子我回去发你\n"
    "对方: 好，我也想换一双\n"
    "我: 爬山鞋还是别省，脚舒服很重要\n"
    "对方: 有道理\n"
  },
};

#define CONV_NSEEDS (sizeof(g_seeds) / sizeof(g_seeds[0]))

/* Visitor state for the listing and sending paths. */

struct conv_list_ctx_s
{
  bool as_json;
  bool first;
};

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static void conv_usage(void)
{
  printf(
    "Usage: conv <seed|list|find|get|send> [options]\n"
    "\n"
    "  seed -d <YYYYMMDD>\n"
    "        write %u sample conversations, dated relative to the day given.\n"
    "        The date is required: this board's time(NULL) returns seconds\n"
    "        since boot, so it cannot know today's date on its own.\n"
    "\n"
    "  list  print the whole index\n"
    "\n"
    "  find [-s <YYYYMMDD>] [-e <YYYYMMDD>] [-c <cue>] [-k <keyword>]\n"
    "       [-m <confidence>] [-u]\n"
    "        -s/-e  inclusive date range\n"
    "        -c     social-cue/v1 cue, e.g. brow_furrow\n"
    "        -k     substring of the transcript\n"
    "        -m     minimum overall_confidence, e.g. 0.7\n"
    "        -u     include records the model could not judge\n"
    "\n"
    "  get <seq>\n"
    "        print one conversation's transcript and analysis\n"
    "\n"
    "  send <ip> <port> [same filters as find]\n"
    "        POST every matching record, with its recording, to the console\n"
    "\n"
    "  -j    print results as JSON instead of a table\n",
    (unsigned int)CONV_NSEEDS);
}

/****************************************************************************
 * Name: conv_print_entry
 ****************************************************************************/

static int conv_print_entry(const struct conv_entry_s *entry, void *arg)
{
  struct conv_list_ctx_s *ctx = arg;

  if (ctx->as_json)
    {
      /* Built with printf rather than a serialiser: the board only ever
       * writes JSON, never reads it, and writing it is this cheap.
       */

      printf("%s{\"seq\":%u,\"date\":%u,\"epoch\":%lu,\"duration_ms\":%u,"
             "\"cue\":\"%s\",\"confidence\":%.2f,\"unable_to_judge\":%s,"
             "\"audio_bytes\":%zu,\"summary\":\"%s\"}",
             ctx->first ? "" : ",\n",
             entry->seq, conv_epoch_to_date(entry->epoch),
             (unsigned long)entry->epoch, entry->duration_ms,
             entry->cue, (double)entry->confidence,
             entry->unable_to_judge ? "true" : "false",
             entry->audio_bytes, entry->summary);
    }
  else
    {
      printf("  %3u  %u  %2u.%03us  %-14s %.2f%s  %6zuB  %s\n",
             entry->seq, conv_epoch_to_date(entry->epoch),
             entry->duration_ms / 1000, entry->duration_ms % 1000,
             entry->cue[0] != '\0' ? entry->cue : "(none)",
             (double)entry->confidence,
             entry->unable_to_judge ? "?" : " ",
             entry->audio_bytes, entry->summary);
    }

  ctx->first = false;
  return 0;
}

/****************************************************************************
 * Name: conv_seed
 *
 * Description:
 *   Write the sample set, dated relative to a day the caller supplies.
 *
 *   Each record gets a real Ogg Opus recording rather than a placeholder, so
 *   that what the web console receives is a file it can actually play and
 *   the transfer path is exercised on real data.  A tone is not a
 *   conversation, but it is a valid recording of the right shape and size.
 *
 ****************************************************************************/

static int conv_seed(unsigned int today, bool with_audio)
{
  uint32_t base = conv_date_to_epoch(today, false);
  unsigned int i;
  int ret;

  if (base == 0)
    {
      printf("conv: -d wants a date like 20260818\n");
      return -EINVAL;
    }

  for (i = 0; i < CONV_NSEEDS; i++)
    {
      const struct conv_seed_s *s = &g_seeds[i];
      struct conv_entry_s entry;
      char cue_json[512];
      void *audio = NULL;
      size_t audio_len = 0;

      memset(&entry, 0, sizeof(entry));

      /* day_offset is negative, and base is unsigned: add the seconds rather
       * than subtracting into a wrap.
       */

      entry.epoch = base + (uint32_t)(s->day_offset * 86400) +
                    s->hour * 3600u + s->minute * 60u;
      entry.duration_ms = s->duration_ms;
      entry.confidence = s->confidence;
      entry.unable_to_judge = s->unable_to_judge;
      strncpy(entry.cue, s->cue, sizeof(entry.cue) - 1);
      strncpy(entry.summary, s->summary, sizeof(entry.summary) - 1);

      snprintf(cue_json, sizeof(cue_json),
               "{\n"
               "  \"schema\": \"social-cue/v1\",\n"
               "  \"cues\": [\n"
               "    { \"cue\": \"%s\", \"meaning\": \"%s\","
               " \"confidence\": %.2f }\n"
               "  ],\n"
               "  \"overall_confidence\": %.2f,\n"
               "  \"unable_to_judge\": %s,\n"
               "  \"reason\": \"%s\",\n"
               "  \"suggestion\": \"%s\"\n"
               "}\n",
               s->cue, s->meaning, (double)s->confidence,
               (double)s->confidence,
               s->unable_to_judge ? "true" : "false",
               s->reason, s->suggestion);

      if (with_audio)
        {
          /* A different tone per record, so a listener can tell which
           * recording arrived.
           */

          ret = conv_make_audio(400 + 120 * (int)i, s->duration_ms,
                                &audio, &audio_len);
          if (ret < 0)
            {
              printf("conv: could not synthesise audio for record %u: %d\n",
                     i + 1, ret);
            }
        }

      ret = conv_store_append(&entry, s->transcript, cue_json, audio,
                              audio_len);
      conv_free_audio(audio);

      if (ret < 0)
        {
          printf("conv: writing record %u failed: %d\n", i + 1, ret);
          return ret;
        }

      printf("conv: wrote %u  %u  %s  %s\n", entry.seq,
             conv_epoch_to_date(entry.epoch),
             entry.cue[0] != '\0' ? entry.cue : "(unjudged)", entry.summary);
    }

  return OK;
}

/****************************************************************************
 * Name: conv_get
 ****************************************************************************/

static int conv_get(unsigned int seq)
{
  char buf[CONV_TEXT_MAX];
  int ret;

  ret = conv_store_read_file(CONV_FMT_TEXT, seq, buf, sizeof(buf));
  if (ret < 0)
    {
      printf("conv: record %u has no transcript: %d\n", seq, ret);
      return ret;
    }

  printf("--- transcript %u ---\n%s", seq, buf);

  ret = conv_store_read_file(CONV_FMT_CUE, seq, buf, sizeof(buf));
  if (ret >= 0)
    {
      printf("--- analysis %u ---\n%s", seq, buf);
    }

  return OK;
}

/****************************************************************************
 * Name: conv_parse_filter
 *
 * Description:
 *   Fill a filter from argv, starting at argv[i].
 *
 * Returned Value:
 *   Zero on success, -EINVAL on a bad option.
 *
 ****************************************************************************/

static int conv_parse_filter(int argc, char *argv[], int start,
                             struct conv_filter_s *filter, bool *as_json)
{
  int i;

  memset(filter, 0, sizeof(*filter));

  for (i = start; i < argc; i++)
    {
      if (strcmp(argv[i], "-j") == 0)
        {
          *as_json = true;
          continue;
        }

      if (strcmp(argv[i], "-u") == 0)
        {
          filter->include_unjudged = true;
          continue;
        }

      if (i + 1 >= argc)
        {
          printf("conv: %s wants a value\n", argv[i]);
          return -EINVAL;
        }

      if (strcmp(argv[i], "-s") == 0)
        {
          filter->from_epoch =
            conv_date_to_epoch((unsigned int)strtoul(argv[i + 1], NULL, 10),
                               false);
          if (filter->from_epoch == 0)
            {
              printf("conv: -s wants a date like 20260801\n");
              return -EINVAL;
            }
        }
      else if (strcmp(argv[i], "-e") == 0)
        {
          /* Inclusive: the end of that day, not its midnight. */

          filter->to_epoch =
            conv_date_to_epoch((unsigned int)strtoul(argv[i + 1], NULL, 10),
                               true);
          if (filter->to_epoch == 0)
            {
              printf("conv: -e wants a date like 20260818\n");
              return -EINVAL;
            }
        }
      else if (strcmp(argv[i], "-c") == 0)
        {
          filter->cue = argv[i + 1];
        }
      else if (strcmp(argv[i], "-k") == 0)
        {
          filter->keyword = argv[i + 1];
        }
      else if (strcmp(argv[i], "-m") == 0)
        {
          filter->min_confidence = strtof(argv[i + 1], NULL);
        }
      else
        {
          printf("conv: unknown option %s\n", argv[i]);
          return -EINVAL;
        }

      i++;
    }

  return OK;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(int argc, char *argv[])
{
  struct conv_filter_s filter;
  struct conv_list_ctx_s ctx;
  bool as_json = false;
  int ret;

  if (argc < 2)
    {
      conv_usage();
      return EXIT_FAILURE;
    }

  ret = conv_store_ready();
  if (ret < 0)
    {
      return EXIT_FAILURE;
    }

  if (strcmp(argv[1], "seed") == 0)
    {
      unsigned int today = 0;
      bool with_audio = true;
      int i;

      for (i = 2; i + 1 < argc; i += 2)
        {
          if (strcmp(argv[i], "-d") == 0)
            {
              today = (unsigned int)strtoul(argv[i + 1], NULL, 10);
            }
          else
            {
              conv_usage();
              return EXIT_FAILURE;
            }
        }

      for (i = 2; i < argc; i++)
        {
          if (strcmp(argv[i], "-n") == 0)
            {
              with_audio = false;
            }
        }

      if (today == 0)
        {
          printf("conv: seed needs -d <YYYYMMDD>; the board has no clock so "
                 "today's date has to come from you\n");
          return EXIT_FAILURE;
        }

      return conv_seed(today, with_audio) < 0 ?
             EXIT_FAILURE : EXIT_SUCCESS;
    }

  if (strcmp(argv[1], "get") == 0)
    {
      if (argc < 3)
        {
          printf("Usage: conv get <seq>\n");
          return EXIT_FAILURE;
        }

      return conv_get((unsigned int)strtoul(argv[2], NULL, 10)) < 0 ?
             EXIT_FAILURE : EXIT_SUCCESS;
    }

  if (strcmp(argv[1], "send") == 0)
    {
      if (argc < 4)
        {
          printf("Usage: conv send <ip> <port> [filters]\n");
          return EXIT_FAILURE;
        }

      if (conv_parse_filter(argc, argv, 4, &filter, &as_json) < 0)
        {
          return EXIT_FAILURE;
        }

      return conv_send_matching(argv[2], atoi(argv[3]), &filter) < 0 ?
             EXIT_FAILURE : EXIT_SUCCESS;
    }

  if (strcmp(argv[1], "list") == 0 || strcmp(argv[1], "find") == 0)
    {
      if (conv_parse_filter(argc, argv, 2, &filter, &as_json) < 0)
        {
          return EXIT_FAILURE;
        }

      /* `list` means everything, including what the model could not judge --
       * hiding those from a plain listing would make records disappear with
       * no way to notice.
       */

      if (strcmp(argv[1], "list") == 0)
        {
          filter.include_unjudged = true;
        }

      ctx.as_json = as_json;
      ctx.first = true;

      if (as_json)
        {
          printf("[\n");
        }
      else
        {
          printf("  seq  date      dur      cue            conf  audio   "
                 "summary\n");
        }

      ret = conv_store_query(&filter, conv_print_entry, &ctx);

      if (as_json)
        {
          printf("\n]\n");
        }

      if (ret < 0)
        {
          printf("conv: query failed: %d\n", ret);
          return EXIT_FAILURE;
        }

      if (!as_json)
        {
          printf("conv: %d match(es)\n", ret);
        }

      return EXIT_SUCCESS;
    }

  conv_usage();
  return EXIT_FAILURE;
}

/****************************************************************************
 * app/conv/conv_send.c
 *
 * Shipping matched records to the web console.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <errno.h>
#include <fcntl.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#include <arpa/inet.h>
#include <netinet/in.h>
#include <sys/socket.h>

#include <arch/chip/bk7258_psram.h>

#include "../audio_test/audio_test_ogg.h"
#include "conv_send.h"
#include "conv_store.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* Sample rate for synthesised recordings.  16 kHz because that is what the
 * ADC produces and one of the rates Opus takes natively, so a seeded file
 * and a real one differ only in content.
 */

#define CONV_RATE         16000
#define CONV_BITRATE      24000

/* Ceiling on one encoded recording.  Fifteen seconds at 24 kbps is about
 * 45 KiB; 128 KiB leaves room for VBR and costs nothing in PSRAM.
 */

#define CONV_AUDIO_CAP    (128 * 1024)

/* Send timeout.  A console that has gone away must not hold this command. */

#define CONV_SEND_MS      3000

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: conv_encode_percent
 *
 * Description:
 *   Percent-encode into a header value.
 *
 *   Needed because the summaries are UTF-8 Chinese and a header is defined
 *   over bytes that a proxy may fold, and because a newline in a header
 *   value would end the header block early -- turning a summary that happens
 *   to contain one into a malformed request rather than a garbled string.
 *
 *   Everything outside unreserved ASCII is encoded, which for Chinese text
 *   means all of it.  That triples the length, which is why only the summary
 *   travels this way and not the transcript.
 *
 ****************************************************************************/

static void conv_encode_percent(const char *src, char *dst, size_t dstlen)
{
  static const char hex[] = "0123456789ABCDEF";
  size_t o = 0;

  while (*src != '\0' && o + 4 < dstlen)
    {
      unsigned char c = (unsigned char)*src++;

      if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
          (c >= '0' && c <= '9') || c == '-' || c == '_' || c == '.' ||
          c == '~')
        {
          dst[o++] = (char)c;
        }
      else
        {
          dst[o++] = '%';
          dst[o++] = hex[(c >> 4) & 0x0f];
          dst[o++] = hex[c & 0x0f];
        }
    }

  dst[o] = '\0';
}

/****************************************************************************
 * Name: conv_connect
 ****************************************************************************/

static int conv_connect(const char *host, int port)
{
  struct sockaddr_in addr;
  struct timeval tv;
  int sock;

  memset(&addr, 0, sizeof(addr));
  addr.sin_family = AF_INET;
  addr.sin_port = htons((uint16_t)port);
  if (inet_pton(AF_INET, host, &addr.sin_addr) != 1)
    {
      printf("conv: %s is not an IPv4 address\n", host);
      return -EINVAL;
    }

  sock = socket(AF_INET, SOCK_STREAM, 0);
  if (sock < 0)
    {
      return -errno;
    }

  if (connect(sock, (struct sockaddr *)&addr, sizeof(addr)) < 0)
    {
      int err = errno;

      close(sock);
      return -err;
    }

  tv.tv_sec = CONV_SEND_MS / 1000;
  tv.tv_usec = 0;
  setsockopt(sock, SOL_SOCKET, SO_SNDTIMEO, &tv, sizeof(tv));
  setsockopt(sock, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));

  return sock;
}

/****************************************************************************
 * Name: conv_send_all
 ****************************************************************************/

static int conv_send_all(int sock, const void *data, size_t len)
{
  const uint8_t *p = data;
  size_t sent = 0;

  while (sent < len)
    {
      ssize_t n = send(sock, p + sent, len - sent, 0);

      if (n <= 0)
        {
          if (n < 0 && errno == EINTR)
            {
              continue;
            }

          return n < 0 ? -errno : -EIO;
        }

      sent += (size_t)n;
    }

  return OK;
}

/****************************************************************************
 * Name: conv_send_one
 ****************************************************************************/

static int conv_send_one(const char *host, int port,
                         const struct conv_entry_s *entry)
{
  char header[768];
  char summary[CONV_SUMMARY_MAX * 3 + 4];
  char reply[96];
  char path[64];
  uint8_t *audio = NULL;
  size_t audio_len = 0;
  int sock;
  int len;
  int ret;
  int fd;

  /* The recording is read into PSRAM: it is up to tens of kilobytes and the
   * SRAM heap has other uses, while nothing here is latency-sensitive.
   */

  if (entry->audio_bytes > 0)
    {
      snprintf(path, sizeof(path), CONV_FMT_AUDIO, entry->seq);

      fd = open(path, O_RDONLY);
      if (fd >= 0)
        {
          audio = bk7258_psram_malloc(entry->audio_bytes);
          if (audio != NULL)
            {
              ssize_t got = read(fd, audio, entry->audio_bytes);

              audio_len = got > 0 ? (size_t)got : 0;
            }

          close(fd);
        }
    }

  conv_encode_percent(entry->summary, summary, sizeof(summary));

  sock = conv_connect(host, port);
  if (sock < 0)
    {
      bk7258_psram_free(audio);
      return sock;
    }

  len = snprintf(header, sizeof(header),
                 "POST /v1/conv/record HTTP/1.1\r\n"
                 "Host: %s:%d\r\n"
                 "User-Agent: bk7258-conv\r\n"
                 "Content-Type: audio/ogg\r\n"
                 "Content-Length: %zu\r\n"
                 "X-Seq: %u\r\n"
                 "X-Date: %u\r\n"
                 "X-Epoch: %lu\r\n"
                 "X-Duration-Ms: %u\r\n"
                 "X-Cue: %s\r\n"
                 "X-Confidence: %.2f\r\n"
                 "X-Unable-To-Judge: %s\r\n"
                 "X-Summary: %s\r\n"
                 "Connection: close\r\n"
                 "\r\n",
                 host, port, audio_len, entry->seq,
                 conv_epoch_to_date(entry->epoch),
                 (unsigned long)entry->epoch, entry->duration_ms,
                 entry->cue[0] != '\0' ? entry->cue : "none",
                 (double)entry->confidence,
                 entry->unable_to_judge ? "true" : "false",
                 summary);

  if (len <= 0 || (size_t)len >= sizeof(header))
    {
      close(sock);
      bk7258_psram_free(audio);
      return -EINVAL;
    }

  ret = conv_send_all(sock, header, (size_t)len);
  if (ret == OK && audio_len > 0)
    {
      ret = conv_send_all(sock, audio, audio_len);
    }

  bk7258_psram_free(audio);

  if (ret == OK)
    {
      ssize_t got = recv(sock, reply, sizeof(reply) - 1, 0);

      /* A receiver that closes without answering has still taken the bytes,
       * so that is not an error -- but a receiver that answers with anything
       * other than success is.
       */

      if (got > 0)
        {
          reply[got] = '\0';
          if (strstr(reply, " 200") == NULL &&
              strstr(reply, " 204") == NULL)
            {
              printf("conv: record %u rejected: %.40s\n", entry->seq, reply);
              ret = -EIO;
            }
        }
    }

  close(sock);
  return ret;
}

/****************************************************************************
 * Name: conv_send_visit
 ****************************************************************************/

struct conv_send_ctx_s
{
  const char *host;
  int port;
  int sent;
  int failed;
};

static int conv_send_visit(const struct conv_entry_s *entry, void *arg)
{
  struct conv_send_ctx_s *ctx = arg;
  int ret = conv_send_one(ctx->host, ctx->port, entry);

  if (ret < 0)
    {
      ctx->failed++;
      printf("conv: record %u failed: %d\n", entry->seq, ret);

      /* Keep going: one unreachable moment should not abandon the rest of a
       * result set the user asked for.
       */

      return 0;
    }

  ctx->sent++;
  printf("conv: sent %u  %u  %zu byte(s)\n", entry->seq,
         conv_epoch_to_date(entry->epoch), entry->audio_bytes);
  return 0;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int conv_send_matching(const char *host, int port,
                       const struct conv_filter_s *filter)
{
  struct conv_send_ctx_s ctx;
  int ret;

  ctx.host = host;
  ctx.port = port;
  ctx.sent = 0;
  ctx.failed = 0;

  ret = conv_store_query(filter, conv_send_visit, &ctx);
  if (ret < 0)
    {
      return ret;
    }

  printf("conv: %d matched, %d sent, %d failed\n", ret, ctx.sent,
         ctx.failed);

  return ctx.failed > 0 && ctx.sent == 0 ? -EIO : ctx.sent;
}

int conv_make_audio(int tone_hz, unsigned int duration_ms, void **audio,
                    size_t *audio_len)
{
  size_t nsamples = (size_t)CONV_RATE * duration_ms / 1000u;
  int16_t *pcm;
  uint8_t *out;
  void *handle;
  size_t len = 0;
  size_t i;
  int ret;

  if (audio == NULL || audio_len == NULL || nsamples == 0)
    {
      return -EINVAL;
    }

  *audio = NULL;
  *audio_len = 0;

  pcm = bk7258_psram_malloc(nsamples * sizeof(int16_t));
  out = bk7258_psram_malloc(CONV_AUDIO_CAP);
  if (pcm == NULL || out == NULL)
    {
      bk7258_psram_free(pcm);
      bk7258_psram_free(out);
      return -ENOMEM;
    }

  for (i = 0; i < nsamples; i++)
    {
      float phase = 2.0f * (float)M_PI * (float)tone_hz *
                    (float)i / (float)CONV_RATE;

      /* A third of full scale: loud enough to hear, quiet enough that
       * nobody reaches for the volume before realising it is a test tone.
       */

      pcm[i] = (int16_t)(10000.0f * sinf(phase));
    }

  /* PSRAM for the encoder state: this runs from an NSH command with the
   * SRAM heap shared by everything else, and the encode is not on any
   * deadline here.
   */

  handle = audio_test_ogg_encoder_create(CONV_RATE, CONV_BITRATE, true);
  if (handle == NULL)
    {
      bk7258_psram_free(pcm);
      bk7258_psram_free(out);
      return -ENOMEM;
    }

  ret = audio_test_ogg_encode(handle, pcm, nsamples, 0x434f4e56u,
                              out, CONV_AUDIO_CAP, &len);
  audio_test_ogg_encoder_destroy(handle);
  bk7258_psram_free(pcm);

  if (ret < 0)
    {
      bk7258_psram_free(out);
      return ret;
    }

  *audio = out;
  *audio_len = len;
  return OK;
}

void conv_free_audio(void *audio)
{
  bk7258_psram_free(audio);
}

