   * records it names are still enumerable, so an interrupted clear can be
   * repeated rather than leaving orphans nothing knows about.
   */

  if (unlink(CONV_INDEX) < 0 && errno != ENOENT)
    {
      return -errno;
    }

  return removed;
}

