/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: ws_b64_16
 *
 * Description:
 *   Base64-encode 16 bytes into the 24-character form Sec-WebSocket-Key
 *   requires.
 *
 ****************************************************************************/

static void ws_b64_16(const uint8_t *in, char *out)
{
  int i;
  int o = 0;

  for (i = 0; i < 15; i += 3)
    {
      uint32_t v = ((uint32_t)in[i] << 16) | ((uint32_t)in[i + 1] << 8) |
                   in[i + 2];

      out[o++] = g_ws_b64[(v >> 18) & 0x3f];
      out[o++] = g_ws_b64[(v >> 12) & 0x3f];
      out[o++] = g_ws_b64[(v >> 6) & 0x3f];
      out[o++] = g_ws_b64[v & 0x3f];
    }

  /* The sixteenth byte on its own: two output characters and one pad. */

  out[o++] = g_ws_b64[(in[15] >> 2) & 0x3f];
  out[o++] = g_ws_b64[(in[15] << 4) & 0x3f];
  out[o++] = '=';
  out[o++] = '=';
  out[o] = '\0';
}

/****************************************************************************
 * Name: ws_random
 *
 * Description:
 *   Fill a buffer with random bytes for the handshake key and the frame
 *   masks.
 *
 *   The mask is not a security measure -- the payload travels in clear
 *   either way -- it exists so that a hostile page cannot make a client emit
 *   bytes of its choosing at a proxy.  arc4random is seeded from the kernel
 *   pool, which this board's TRNG feeds, so it is a better source than
 *   anything this file could build from the clock.
 *
 ****************************************************************************/

static void ws_random(uint8_t *buf, size_t len)
{
  arc4random_buf(buf, len);
}

/****************************************************************************
 * Name: ws_send_all
 ****************************************************************************/

static int ws_send_all(int sock, const void *data, size_t len)
{
  const uint8_t *p = data;
  size_t sent = 0;

  while (sent < len)
    {
      ssize_t n = send(sock, p + sent, len - sent, 0);

      if (n <= 0)
        {
          if (n < 0 && errno == EINTR)
            {
              continue;
            }

          return n < 0 ? -errno : -EIO;
        }

      sent += (size_t)n;
    }

  return OK;
}

/****************************************************************************
 * Name: ws_recv_exact
 *
 * Description:
 *   Read exactly len bytes, or fail.
 *
 *   Framing needs this: a header read that comes up short would otherwise be
 *   interpreted as a frame, and the stream would never resynchronise.
 *
 ****************************************************************************/

static int ws_recv_exact(int sock, void *data, size_t len)
{
  uint8_t *p = data;
  size_t got = 0;

  while (got < len)
    {
      ssize_t n = recv(sock, p + got, len - got, 0);

      if (n == 0)
        {
          return -ENOTCONN;
        }

      if (n < 0)
        {
          if (errno == EINTR)
            {
              continue;
            }

          return -errno;
        }

      got += (size_t)n;
    }

  return OK;
}

/****************************************************************************
 * Name: ws_send_frame
 *
 * Description:
 *   Send one masked frame with the given opcode.
 *
 ****************************************************************************/

static int ws_send_frame(struct conv_ws_s *ws, uint8_t opcode,
                         const void *payload, size_t len)
{
  uint8_t header[14];
  uint8_t mask[4];
  uint8_t chunk[256];
  const uint8_t *src = payload;
  size_t offset = 0;
  size_t hlen = 0;
  int ret;

  if (len > CONV_WS_MAX_MSG)
    {
      printf("conv: refusing to send a %zu byte frame; the console's limit "
             "is %d\n", len, CONV_WS_MAX_MSG);
      return -EMSGSIZE;
    }

  header[hlen++] = 0x80 | opcode;          /* FIN set, single frame */

  if (len < 126)
    {
      header[hlen++] = 0x80 | (uint8_t)len;
    }
  else
    {
      header[hlen++] = 0x80 | 126;
      header[hlen++] = (uint8_t)((len >> 8) & 0xff);
      header[hlen++] = (uint8_t)(len & 0xff);
    }

  ws_random(mask, sizeof(mask));
  memcpy(header + hlen, mask, sizeof(mask));
  hlen += sizeof(mask);

  ret = ws_send_all(ws->sock, header, hlen);
  if (ret < 0)
    {
      return ret;
    }

  /* Masked in blocks rather than in place: the caller's buffer is not ours
   * to modify, and copying the whole payload only to XOR it would double the
   * memory for a 16 KB message.
   */

  while (offset < len)
    {
      size_t n = len - offset;
      size_t i;

      if (n > sizeof(chunk))
        {
          n = sizeof(chunk);
        }

      for (i = 0; i < n; i++)
        {
          chunk[i] = src[offset + i] ^ mask[(offset + i) & 3];
        }

      ret = ws_send_all(ws->sock, chunk, n);
      if (ret < 0)
        {
          return ret;
        }

      offset += n;
    }

  return OK;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int conv_ws_connect(struct conv_ws_s *ws, const char *host, int port)
{
  struct sockaddr_in addr;
  struct timeval tv;
  uint8_t keybytes[16];
  char key[32];
  char request[512];
  char response[512];
  size_t total = 0;
  int len;
  int ret;

  memset(ws, 0, sizeof(*ws));
  ws->sock = -1;

  memset(&addr, 0, sizeof(addr));
  addr.sin_family = AF_INET;
  addr.sin_port = htons((uint16_t)port);
  if (inet_pton(AF_INET, host, &addr.sin_addr) != 1)
    {
      printf("conv: %s is not an IPv4 address\n", host);
      return -EINVAL;
    }

  ws->sock = socket(AF_INET, SOCK_STREAM, 0);
  if (ws->sock < 0)
    {
      return -errno;
    }

  if (connect(ws->sock, (struct sockaddr *)&addr, sizeof(addr)) < 0)
    {
      ret = -errno;
      printf("conv: cannot reach %s:%d: %d\n", host, port, -ret);
      close(ws->sock);
      ws->sock = -1;
      return ret;
    }

  tv.tv_sec = 5;
  tv.tv_usec = 0;
  setsockopt(ws->sock, SOL_SOCKET, SO_SNDTIMEO, &tv, sizeof(tv));
  setsockopt(ws->sock, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));

  ws_random(keybytes, sizeof(keybytes));
  ws_b64_16(keybytes, key);

  len = snprintf(request, sizeof(request),
                 "GET /ws HTTP/1.1\r\n"
                 "Host: %s:%d\r\n"
                 "Upgrade: websocket\r\n"
                 "Connection: Upgrade\r\n"
                 "Sec-WebSocket-Key: %s\r\n"
                 "Sec-WebSocket-Version: 13\r\n"
                 "\r\n",
                 host, port, key);

  ret = ws_send_all(ws->sock, request, (size_t)len);
  if (ret < 0)
    {
      close(ws->sock);
      ws->sock = -1;
      return ret;
    }

  /* Read until the end of the header block.  The server sends nothing else
   * until the client speaks, so this cannot swallow a frame.
   */

  while (total < sizeof(response) - 1)
    {
      ssize_t got = recv(ws->sock, response + total,
                         sizeof(response) - 1 - total, 0);

      if (got <= 0)
        {
          break;
        }

      total += (size_t)got;
      response[total] = '\0';

      if (strstr(response, "\r\n\r\n") != NULL)
        {
          break;
        }
    }

  response[total] = '\0';

  if (strstr(response, " 101") == NULL)
    {
      /* Print the status line: a 403 or a 404 here means the path or the
       * server is wrong, and that is worth seeing rather than "handshake
       * failed".
       */

      char *eol = strstr(response, "\r\n");

      if (eol != NULL)
        {
          *eol = '\0';
        }

      printf("conv: %s:%d did not upgrade: %.60s\n", host, port,
             total > 0 ? response : "(no reply)");
      close(ws->sock);
      ws->sock = -1;
      return -EPROTO;
    }

  ws->connected = true;
  return OK;
}

void conv_ws_close(struct conv_ws_s *ws)
{
  if (ws->sock >= 0)
    {
      if (ws->connected)
        {
          /* Best effort: a close frame is courtesy, and the socket is going
           * away regardless of whether it lands.
           */

          uint8_t reason[2];

          reason[0] = 0x03;
          reason[1] = 0xe8;                /* 1000, normal closure */
          ws_send_frame(ws, WS_OP_CLOSE, reason, sizeof(reason));
        }

      close(ws->sock);
      ws->sock = -1;
    }

  ws->connected = false;
}

int conv_ws_send_text(struct conv_ws_s *ws, const char *text)
{
  if (!ws->connected)
    {
      return -ENOTCONN;
    }

  return ws_send_frame(ws, WS_OP_TEXT, text, strlen(text));
}

int conv_ws_recv_text(struct conv_ws_s *ws, char *buf, size_t len,
                      int timeout_ms)
{
  for (; ; )
    {
      struct pollfd pfd;
      uint8_t header[2];
      size_t payload;
      uint8_t opcode;
      int ret;

      if (!ws->connected)
        {
          return -ENOTCONN;
        }

      pfd.fd = ws->sock;
      pfd.events = POLLIN;
      pfd.revents = 0;

      ret = poll(&pfd, 1, timeout_ms > 0 ? timeout_ms : -1);
      if (ret == 0)
        {
          return 0;
        }

      if (ret < 0)
        {
          return errno == EINTR ? 0 : -errno;
        }

      ret = ws_recv_exact(ws->sock, header, sizeof(header));
      if (ret < 0)
        {
          ws->connected = false;
          return ret;
        }

      opcode = header[0] & 0x0f;

      if ((header[0] & 0x80) == 0)
        {
          printf("conv: the console sent a fragmented frame, which this "
                 "client does not reassemble\n");
          ws->connected = false;
          return -EPROTO;
        }

      payload = header[1] & 0x7f;

      if (payload == 126)
        {
          uint8_t ext[2];

          ret = ws_recv_exact(ws->sock, ext, sizeof(ext));
          if (ret < 0)
            {
              ws->connected = false;
              return ret;
            }

          payload = ((size_t)ext[0] << 8) | ext[1];
        }
      else if (payload == 127)
        {
          printf("conv: the console sent a 64-bit length, which cannot be "
                 "right against its own %d byte limit\n", CONV_WS_MAX_MSG);
          ws->connected = false;
          return -EMSGSIZE;
        }

      /* A server frame is never masked; if one were, the payload would be
       * garbage and the mask bytes would be read as data.
       */

      if ((header[1] & 0x80) != 0)
        {
          printf("conv: the console masked a frame, which servers must "
                 "not\n");
          ws->connected = false;
          return -EPROTO;
        }

      if (payload > len - 1)
        {
          printf("conv: a %zu byte frame does not fit the %zu byte "
                 "buffer\n", payload, len);
          ws->connected = false;
          return -EMSGSIZE;
        }

      if (payload > 0)
        {
          ret = ws_recv_exact(ws->sock, buf, payload);
          if (ret < 0)
            {
              ws->connected = false;
              return ret;
            }
        }

      buf[payload] = '\0';

      switch (opcode)
        {
          case WS_OP_TEXT:
            return (int)payload;

          case WS_OP_PING:

            /* Answered rather than ignored: the server is entitled to drop a
             * peer that stops responding, and a history query that fails
             * because a keepalive went unanswered would look like a bug in
             * the query.
             */

            ws_send_frame(ws, WS_OP_PONG, buf, payload);
            break;

          case WS_OP_PONG:
            break;

          case WS_OP_CLOSE:
            ws->connected = false;
            return -ENOTCONN;

          default:
            printf("conv: ignoring opcode 0x%x\n", opcode);
            break;
        }
    }
}

/****************************************************************************
 * app/conv/conv_serve.c
 *
 * Staying connected to the web console and answering the queries it forwards.
 *
 * Until this existed the board could only be asked from its own shell: the
 * query ran where the recordings are, which is right, but the only way to
 * start one was to type it on the serial console.  The browser had no way to
 * reach it.  This closes that: the console forwards a query, the board runs
 * it against its index, and the result goes back over the same connection.
 *
 * Recordings do not go back that way.  The console's frame limit is 16 KB and
 * a recording is tens of kilobytes, so audio is pushed over HTTP on demand --
 * one record at a time, only when the browser opens one, because most rows in
 * a result are never opened.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#include "conv_send.h"
#include "conv_store.h"
#include "conv_ws.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* Room for one outgoing message.  Bounded by what the console accepts, and
 * checked while filling rather than after: a result set that would overflow
 * is truncated with a flag, not silently cut in the middle of a JSON object.
 */

#define SERVE_OUT_MAX     CONV_WS_MAX_MSG

/* Longest string value read out of an incoming message. */

#define SERVE_FIELD_MAX   64

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct serve_ctx_s
{
  char *out;
  size_t cap;
  size_t len;
  int emitted;
  bool truncated;
};

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: serve_json_int / serve_json_str
 *
 * Description:
 *   Pull one field out of a JSON message by name.
 *
 *   Substring matching, not parsing.  The peer is one known server sending
 *   messages this project defines, and a parser plus its working memory is a
 *   poor trade for reading four fields.  The cost is that a *value* which
 *   contains the text of another key could mislead it -- a keyword of
 *   `"cue":"x"` for instance.  That is accepted here because the fields are
 *   read left to right from the key that was asked for, so only a value
 *   deliberately crafted to look like a key can do it, and this connection
 *   carries no untrusted input.  If it ever does, this is the first thing to
 *   replace.
 *
 ****************************************************************************/

static bool serve_json_int(const char *msg, const char *key, long *value)
{
  char pattern[SERVE_FIELD_MAX];
  const char *p;

  snprintf(pattern, sizeof(pattern), "\"%s\"", key);

  p = strstr(msg, pattern);
  if (p == NULL)
    {
      return false;
    }

  p = strchr(p, ':');
  if (p == NULL)
    {
      return false;
    }

  *value = strtol(p + 1, NULL, 10);
  return true;
}

static bool serve_json_str(const char *msg, const char *key, char *out,
                           size_t len)
{
  char pattern[SERVE_FIELD_MAX];
  const char *p;
  size_t o = 0;

  snprintf(pattern, sizeof(pattern), "\"%s\"", key);

  p = strstr(msg, pattern);
  if (p == NULL)
    {
      return false;
    }

  p = strchr(p, ':');
  if (p == NULL)
    {
      return false;
    }

  p++;
  while (*p == ' ')
    {
      p++;
    }

  if (*p != '"')
    {
      return false;
    }

  p++;
  while (*p != '\0' && *p != '"' && o + 1 < len)
    {
      /* Escapes are passed through as-is except for the quote, which is the
       * only one that would end the value early.  The console does not send
       * escaped keywords today; anything else arriving is left for the
       * comparison to fail on rather than being silently altered.
       */

      if (*p == '\\' && p[1] == '"')
        {
          out[o++] = '"';
          p += 2;
          continue;
        }

      out[o++] = *p++;
    }

  out[o] = '\0';
  return o > 0;
}

/****************************************************************************
 * Name: serve_append
 *
 * Description:
 *   Append to the outgoing message, refusing to overflow.
 *
 * Returned Value:
 *   True if it fitted.
 *
 ****************************************************************************/

static bool serve_append(struct serve_ctx_s *ctx, const char *fmt, ...)
{
  va_list ap;
  int n;

  va_start(ap, fmt);
  n = vsnprintf(ctx->out + ctx->len, ctx->cap - ctx->len, fmt, ap);
  va_end(ap);

  if (n < 0 || (size_t)n >= ctx->cap - ctx->len)
    {
      /* Roll back the partial write: half a JSON object is worse than a
       * short list with a flag saying it was cut.
       */

      ctx->out[ctx->len] = '\0';
      ctx->truncated = true;
      return false;
    }

  ctx->len += (size_t)n;
  return true;
}

/****************************************************************************
 * Name: serve_visit
 ****************************************************************************/

static int serve_visit(const struct conv_entry_s *entry, void *arg)
{
  struct serve_ctx_s *ctx = arg;

  if (ctx->truncated)
    {
      return 0;
    }

  serve_append(ctx,
               "%s{\"seq\":%u,\"date\":%u,\"epoch\":%lu,"
               "\"durationMs\":%u,\"cue\":\"%s\",\"confidence\":%.2f,"
               "\"unableToJudge\":%s,\"audioBytes\":%zu,"
               "\"summary\":\"%s\"}",
               ctx->emitted > 0 ? "," : "",
               entry->seq, conv_epoch_to_date(entry->epoch),
               (unsigned long)entry->epoch, entry->duration_ms,
               entry->cue, (double)entry->confidence,
               entry->unable_to_judge ? "true" : "false",
               entry->audio_bytes, entry->summary);

  if (!ctx->truncated)
    {
      ctx->emitted++;
    }

  return 0;
}

/****************************************************************************
 * Name: serve_handle_query
 ****************************************************************************/

static int serve_handle_query(struct conv_ws_s *ws, const char *msg,
                              char *out, size_t outcap)
{
  struct conv_filter_s filter;
  struct serve_ctx_s ctx;
  char request_id[SERVE_FIELD_MAX];
  char cue[CONV_CUE_MAX];
  char keyword[SERVE_FIELD_MAX];
  long value;
  int ret;

  memset(&filter, 0, sizeof(filter));

  if (!serve_json_str(msg, "requestId", request_id, sizeof(request_id)))
    {
      strncpy(request_id, "unknown", sizeof(request_id) - 1);
      request_id[sizeof(request_id) - 1] = '\0';
    }

  /* Dates arrive as YYYYMMDD, the same form the command line takes, so the
   * console and the shell cannot disagree about what a date means.
   */

  if (serve_json_int(msg, "from", &value) && value > 0)
    {
      filter.from_epoch = conv_date_to_epoch((unsigned int)value, false);
    }

  if (serve_json_int(msg, "to", &value) && value > 0)
    {
      filter.to_epoch = conv_date_to_epoch((unsigned int)value, true);
    }

  if (serve_json_str(msg, "cue", cue, sizeof(cue)))
    {
      filter.cue = cue;
    }

  if (serve_json_str(msg, "keyword", keyword, sizeof(keyword)))
    {
      filter.keyword = keyword;
    }

  if (serve_json_int(msg, "minConfidence", &value))
    {
      /* Sent as a percentage so the field stays an integer: JSON floats
       * would work but this avoids a locale-sensitive strtof on a value that
       * only ever has two digits of meaning.
       */

      filter.min_confidence = (float)value / 100.0f;
    }

  filter.include_unjudged = strstr(msg, "\"includeUnjudged\":true") != NULL;

  ctx.out = out;
  ctx.cap = outcap;
  ctx.len = 0;
  ctx.emitted = 0;
  ctx.truncated = false;

  serve_append(&ctx, "{\"type\":\"query_result\",\"requestId\":\"%s\","
                     "\"records\":[", request_id);

  ret = conv_store_query(&filter, serve_visit, &ctx);
  if (ret < 0)
    {
      snprintf(out, outcap,
               "{\"type\":\"query_result\",\"requestId\":\"%s\","
               "\"error\":\"query failed: %d\"}", request_id, ret);
      return conv_ws_send_text(ws, out);
    }

  serve_append(&ctx, "],\"matched\":%d,\"returned\":%d,\"truncated\":%s}",
               ret, ctx.emitted, ctx.truncated ? "true" : "false");

  if (ctx.truncated)
    {
      printf("conv: %d match(es) did not fit one frame, sent %d\n", ret,
             ctx.emitted);
    }
  else
    {
      printf("conv: query %s -> %d match(es)\n", request_id, ret);
    }

  return conv_ws_send_text(ws, out);
}

/****************************************************************************
 * Name: serve_handle_fetch
 *
 * Description:
 *   Push one record's recording to the console over HTTP, then say so.
 *
 *   On demand rather than with the query: a result set is mostly rows nobody
 *   opens, and pushing every recording would move a megabyte to answer a
 *   question about six.
 *
 ****************************************************************************/

static int serve_handle_fetch(struct conv_ws_s *ws, const char *msg,
                             const char *host, int port, char *out,
                             size_t outcap)
{
  struct conv_filter_s filter;
  char request_id[SERVE_FIELD_MAX];
  long seq = 0;
  int ret;

  if (!serve_json_str(msg, "requestId", request_id, sizeof(request_id)))
    {
      strncpy(request_id, "unknown", sizeof(request_id) - 1);
      request_id[sizeof(request_id) - 1] = '\0';
    }

  if (!serve_json_int(msg, "seq", &seq) || seq <= 0)
    {
      snprintf(out, outcap,
               "{\"type\":\"fetch_done\",\"requestId\":\"%s\","
               "\"error\":\"fetch needs a seq\"}", request_id);
      return conv_ws_send_text(ws, out);
    }

  /* Reuse the sending path rather than duplicating it: a filter that selects
   * exactly this record leaves one implementation of "upload a record".
   */

  memset(&filter, 0, sizeof(filter));
  filter.include_unjudged = true;
  filter.from_epoch = 0;
  filter.to_epoch = 0;

  ret = conv_send_seq(host, port, (unsigned int)seq);

  if (ret < 0)
    {
      snprintf(out, outcap,
               "{\"type\":\"fetch_done\",\"requestId\":\"%s\",\"seq\":%ld,"
               "\"error\":\"upload failed: %d\"}", request_id, seq, ret);
    }
  else
    {
      snprintf(out, outcap,
               "{\"type\":\"fetch_done\",\"requestId\":\"%s\",\"seq\":%ld,"
               "\"url\":\"/records/%04ld.ogg\"}", request_id, seq, seq);
    }

  return conv_ws_send_text(ws, out);
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int conv_serve(const char *host, int port)
{
  struct conv_ws_s ws;
  char *in;
  char *out;
  char hello[256];
  long epoch;
  int ret;

  /* Two 16 KB buffers from the heap rather than the stack: this runs from an
   * NSH command whose stack is 8 KB.
   */

  in = malloc(CONV_WS_MAX_MSG);
  out = malloc(SERVE_OUT_MAX);
  if (in == NULL || out == NULL)
    {
      free(in);
      free(out);
      printf("conv: no memory for the message buffers\n");
      return -ENOMEM;
    }

  ret = conv_ws_connect(&ws, host, port);
  if (ret < 0)
    {
      free(in);
      free(out);
      return ret;
    }

  snprintf(hello, sizeof(hello),
           "{\"type\":\"hello\",\"role\":\"board\",\"deviceId\":\"%s\","
           "\"name\":\"%s\"}", "bk7258-001", "VelaSight BK7258");

  ret = conv_ws_send_text(&ws, hello);
  if (ret < 0)
    {
      conv_ws_close(&ws);
      free(in);
      free(out);
      return ret;
    }

  printf("conv: registered with %s:%d, waiting for queries "
         "(Ctrl-C to stop)\n", host, port);

  for (; ; )
    {
      ret = conv_ws_recv_text(&ws, in, CONV_WS_MAX_MSG, 1000);

      if (ret == 0)
        {
          continue;
        }

      if (ret < 0)
        {
          if (ret == -ENOTCONN)
            {
              printf("conv: the console closed the connection\n");
              ret = OK;
            }

          break;
        }

      if (strstr(in, "\"hello_ack\"") != NULL)
        {
