/****************************************************************************
 * Name: conv_seq_visit
 *
 * Description:
 *   Visitor that sends only the record it was asked for.
 *
 *   Implemented through conv_store_query rather than by reading the index
 *   directly so that there is one parser of the index format, not two.
 *
 ****************************************************************************/

struct conv_seq_ctx_s
{
  const char *host;
  int port;
  unsigned int want;
  bool found;
  int ret;
};

static int conv_seq_visit(const struct conv_entry_s *entry, void *arg)
{
  struct conv_seq_ctx_s *ctx = arg;

  if (entry->seq != ctx->want)
    {
      return 0;
    }

  ctx->found = true;
  ctx->ret = conv_send_one(ctx->host, ctx->port, entry);

  /* Stop the scan: returning non-zero ends conv_store_query, and there is
   * only ever one record with a given sequence number.  The value has to be
   * something the caller can tell from a failure, hence the flag.
   */

  return 1;
}

int conv_send_seq(const char *host, int port, unsigned int seq)
{
  struct conv_filter_s filter;
  struct conv_seq_ctx_s ctx;

  memset(&filter, 0, sizeof(filter));

  /* No date or confidence bounds, and unjudged records included: a request
   * for a specific record is not a search, and filtering it out because the
   * model could not read an expression would be surprising.
   */

  filter.include_unjudged = true;

  ctx.host = host;
  ctx.port = port;
  ctx.want = seq;
  ctx.found = false;
  ctx.ret = OK;

  conv_store_query(&filter, conv_seq_visit, &ctx);

  if (!ctx.found)
    {
      printf("conv: no record %u\n", seq);
      return -ENOENT;
    }

  return ctx.ret;
}

