// Read a request body with a hard ceiling.
//
// Bounded because this endpoint is reachable by anything on the LAN: without
// a limit a single request could grow until the process ran out of memory.
function readBody(request, limit) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    let total = 0;
    request.on("data", (chunk) => {
      total += chunk.length;
      if (total > limit) {
        reject(new Error("body too large"));
        request.destroy();
        return;
      }
      chunks.push(chunk);
    });
    request.on("end", () => resolve(Buffer.concat(chunks)));
    request.on("error", reject);
  });
}

// The board POSTs one conversation record here: metadata in headers, the
// recording as the body. Same request shape `conv send` already uses, so the
// board needs no second code path for the WebSocket case.
async function handleRecordUpload(request, response) {
  let body;
  try {
    body = await readBody(request, MAX_UPLOAD_BYTES);
  } catch (error) {
    response.writeHead(413, { "Content-Type": "text/plain; charset=utf-8" });
    response.end(error.message);
    return;
  }

  const seq = Number.parseInt(request.headers["x-seq"] ?? "0", 10);
  if (!Number.isInteger(seq) || seq <= 0) {
    response.writeHead(400, { "Content-Type": "text/plain; charset=utf-8" });
    response.end("X-Seq must be a positive integer");
    return;
  }

  // The summary is percent-encoded: it is UTF-8 Chinese in an HTTP header,
  // and a newline in one would end the header block early.
  const summary = decodeURIComponent(request.headers["x-summary"] ?? "");
  const name = `${String(seq).padStart(4, "0")}.ogg`;

  const record = {
    seq,
    date: request.headers["x-date"] ?? "",
    epoch: request.headers["x-epoch"] ?? "",
    durationMs: request.headers["x-duration-ms"] ?? "",
    cue: request.headers["x-cue"] ?? "",
    confidence: request.headers["x-confidence"] ?? "",
    unableToJudge: request.headers["x-unable-to-judge"] === "true",
    summary,
    audioBytes: body.length,
    url: body.length > 0 ? `/records/${name}` : null,
    receivedAt: new Date().toISOString()
  };

  await mkdir(RECORDS_DIR, { recursive: true });
  if (body.length > 0) await writeFile(join(RECORDS_DIR, name), body);
  await writeFile(join(RECORDS_DIR, `${String(seq).padStart(4, "0")}.json`),
                  JSON.stringify(record, null, 2));

  // Told to the browsers as it arrives, so a row can become playable without
  // the page polling for it.
  broadcastDashboards({ type: "record", ...record });

  console.log(`[record] ${seq} ${record.date} ${record.cue} ${body.length}B ${summary}`);
  response.writeHead(200, { "Content-Type": "text/plain; charset=utf-8" });
  response.end("ok");
}

const server = http.createServer(async (request, response) => {
  const requestPath = new URL(request.url, `http://${request.headers.host}`).pathname;

