const DEVICE_NAME = "BK7258 语音开发板";
const initialSettings = { volume: 50, muted: false };

// ---------------------------------------------------------------------------
// Link to the board, through the server.
//
// The archive search used to filter a hard-coded array in this file. That made
// the page look finished while being unable to see anything the board had
// recorded: a search for a word the board knew returned nothing, identically
// to a search that simply did not match. Everything below replaces that with
// the real path -- dashboard -> server -> board -> back -- and says so when
// the path is not available, rather than answering from a stand-in.
// ---------------------------------------------------------------------------

let socket = null;
let boardId = null;
let requestCounter = 0;
const pending = new Map();

function setLinkStatus(text, kind = "") {
  linkStatus.textContent = text;
  linkStatus.className = `status ${kind}`;
}

function nextRequestId(prefix) {
  requestCounter += 1;
  return `${prefix}-${Date.now().toString(36)}-${requestCounter}`;
}

function connect() {
  // Opened from disk there is no server to reach, and a WebSocket to
  // "ws://" + nothing fails with a message that explains none of it. This is
  // the single most likely way to be looking at a page that does nothing, so
  // it is checked first and named exactly.
  if (location.protocol === "file:") {
    setLinkStatus(
      "这个页面是用 file:// 直接打开的，没有服务器可以连接。请改用 " +
      "http://localhost:8080 打开（在 openvela-web 目录运行 npm start）。",
      "error");
    return;
  }

  const url = `${location.protocol === "https:" ? "wss" : "ws"}://${location.host}/ws`;
  socket = new WebSocket(url);

  socket.addEventListener("open", () => {
    socket.send(JSON.stringify({ type: "hello", role: "dashboard" }));
    setLinkStatus("已连接服务器，正在等待开发板注册…");
  });

  socket.addEventListener("message", (event) => {
    let message;
    try {
      message = JSON.parse(event.data);
    } catch {
      return;
    }
    handleServerMessage(message);
  });

  socket.addEventListener("close", () => {
    boardId = null;
    setLinkStatus("与服务器的连接已断开，5 秒后重连。", "error");
    // Reconnect rather than requiring a refresh: the server is restarted often
    // during development, and a page that silently stops working after one is
    // the same failure this whole section exists to remove.
    setTimeout(connect, 5000);
  });

  socket.addEventListener("error", () => {
    setLinkStatus("无法连接服务器，确认 npm start 正在运行。", "error");
  });
}

function handleServerMessage(message) {
  switch (message.type) {
    case "device_list": {
      const online = (message.devices ?? []).filter((device) => device.online);
      boardId = online.length > 0 ? online[0].deviceId : null;
      if (boardId) {
        setLinkStatus(`开发板已连接：${boardId}。可以查询板上的会话记录。`, "success");
      } else {
        setLinkStatus(
          "服务器已连接，但没有开发板注册。请在板子上运行：" +
          "conv serve <这台电脑的局域网IP> 8080", "error");
      }
      break;
    }

    case "query_result": {
      const resolver = pending.get(message.requestId);
      if (resolver) {
        pending.delete(message.requestId);
        resolver(message);
      }
      break;
    }

    case "fetch_done": {
      const resolver = pending.get(message.requestId);
      if (resolver) {
        pending.delete(message.requestId);
        resolver(message);
      }
      break;
    }

    case "transcript": {
      // The board's live transcription, fed into the session panel that was
      // previously driven only by the buttons on this page.
      appendFinalTranscript(message.text, message.timestamp ?? Date.now());
      break;
    }

    case "error":
      setLinkStatus(`服务器报错：${message.message}`, "error");
      break;

    default:
      break;
  }
}

// Requests carry an id and resolve a promise, so a slow board cannot make an
// old answer land in a new search.
function request(payload, timeoutMs = 15000) {
  return new Promise((resolve, reject) => {
    if (!socket || socket.readyState !== WebSocket.OPEN) {
      reject(new Error("尚未连接服务器"));
      return;
    }
    if (!boardId) {
      reject(new Error("没有开发板在线"));
      return;
    }

    const requestId = nextRequestId(payload.type);
    const timer = setTimeout(() => {
      pending.delete(requestId);
      reject(new Error("开发板在 15 秒内没有回应"));
    }, timeoutMs);

    pending.set(requestId, (message) => {
      clearTimeout(timer);
      if (message.error) {
        reject(new Error(message.error));
        return;
      }
      resolve(message);
    });

    socket.send(JSON.stringify({ ...payload, deviceId: boardId, requestId }));
