// Ask the board to upload one recording, then play the file the server stored.
//
// On demand rather than with the search: the board would otherwise push every
// matching recording, which is tens of kilobytes each to answer a question
// about a list most of whose rows are never opened.
async function loadAndPlay(record, button, audio) {
  if (!record.fromBoard) {
    setLinkStatus("这条记录不是来自开发板，没有可播放的文件。", "error");
    return;
  }

  if (record.audioUrl) {
    audio.hidden = false;
    audio.play();
    return;
  }

  const original = button.textContent;
  button.disabled = true;
  button.textContent = "正在从板子取录音…";

  try {
    const answer = await request({ type: "fetch", seq: record.seq });
    record.audioUrl = answer.url;
    audio.src = answer.url;
    audio.hidden = false;
    button.textContent = "播放";
    await audio.play().catch(() => {
      // Autoplay can be refused; the visible control is still usable, so this
      // is not worth reporting as a failure.
    });
  } catch (error) {
    button.textContent = original;
    setLinkStatus(`取录音失败：${error.message}`, "error");
  } finally {
    button.disabled = false;
  }
}

