// Run the search on the board and render what it returns.
async function runBoardSearch() {
  const keyword = keywordInput.value.trim();
  const cue = cueInput.value.trim();

  searchSummary.textContent = "正在查询开发板…";

  try {
    const answer = await request({
      type: "query",
      from: toBoardDate(startDate.value),
      to: toBoardDate(endDate.value),
      keyword: keyword || undefined,
      cue: cue || undefined,
      // An integer percentage: the board avoids a float parse on a value with
      // two meaningful digits.
      minConfidence: 0,
      // Shown by default. Filtering them out silently would make records
      // vanish with nothing saying why.
      includeUnjudged: true
    });

    archiveRecords = (answer.records ?? []).map(fromBoardRecord);

    let summary = `板上匹配 ${answer.matched} 条，返回 ${answer.returned} 条`;
    if (answer.truncated) {
      summary += "（结果超过一帧上限，已截断，请缩小日期范围）";
    }
    summary += keyword ? `，关键词：“${keyword}”。` : "。";
    renderSearchResults(summary);
  } catch (error) {
    archiveRecords = [];
    renderSearchResults(`查询失败：${error.message}`);
  }
}

