// Stands in for the browser: exercises the three things the page now does --
// search the board, open one row's full dialogue, and store the model
// credentials -- over the same dashboard -> server -> board path the page uses.
//
// A command-line stand-in cannot prove the DOM wiring, but it does prove the
// protocol and the board, so a failure in the page afterwards is isolated to
// the page.

import { WebSocket } from "ws";

const HOST = process.argv[2] ?? "127.0.0.1";
const PORT = Number(process.argv[3] ?? 8080);
const ws = new WebSocket(`ws://${HOST}:${PORT}/ws`);

let deviceId = null;
const pending = new Map();
let counter = 0;

function ask(payload) {
  return new Promise((resolve, reject) => {
    const requestId = `t${++counter}`;
    const timer = setTimeout(() => {
      pending.delete(requestId);
      reject(new Error("timeout"));
    }, 15000);
    pending.set(requestId, (msg) => {
      clearTimeout(timer);
      resolve(msg);
    });
    const out = { ...payload, deviceId, requestId };
    // Never print the key, the same reason the board never returns it.
    const shown = out.key ? { ...out, key: `<${out.key.length} chars>` } : out;
    console.log("-> " + JSON.stringify(shown));
    ws.send(JSON.stringify(out));
  });
}

ws.on("open", () => ws.send(JSON.stringify({ type: "hello", role: "dashboard" })));

ws.on("message", async (data) => {
  const msg = JSON.parse(data.toString());

  if (msg.requestId && pending.has(msg.requestId)) {
    pending.get(msg.requestId)(msg);
    pending.delete(msg.requestId);
    return;
  }

  if (msg.type !== "device_list") return;

  const online = (msg.devices ?? []).filter((d) => d.online);
  if (online.length === 0 || deviceId) return;
  deviceId = online[0].deviceId;
  console.log(`<- device_list: ${deviceId} online`);

  try {
    console.log("\n=== 1. 按日期范围 + 关键词查询 ===");
    const q = await ask({ type: "query", from: 20260810, to: 20260818,
                          keyword: "爬山", minConfidence: 0,
                          includeUnjudged: true });
    console.log(`<- matched=${q.matched} returned=${q.returned}`);
    for (const r of q.records ?? []) {
      console.log(`     seq=${r.seq} ${r.date} ${r.cue} ${r.confidence} ` +
                  `${r.textBytes}B  ${r.summary}`);
    }

    console.log("\n=== 2. 取一条的完整对话 ===");
    const seq = q.records[0].seq;
    const f = await ask({ type: "fetch", seq });
    if (f.error) {
      console.log(`<- error: ${f.error}`);
    } else {
      console.log(`<- seq=${f.seq} 全文 ${f.transcript.length} 字符:`);
      for (const line of f.transcript.split("\n")) {
        if (line) console.log(`     ${line}`);
      }
    }

    console.log("\n=== 3. 存 MiMo key ===");
    const before = await ask({ type: "get_llm" });
    console.log(`<- 当前: ${JSON.stringify(before.config)}`);
    const set = await ask({ type: "set_llm", host: "api.xiaomimimo.com",
                            model: "mimo-v2.5",
                            key: "sk-***REDACTED***" });
    console.log(`<- 保存后: ${JSON.stringify(set.config)}`);
  } catch (error) {
    console.log("FAILED: " + error.message);
  }

  ws.close();
});

ws.on("error", (e) => { console.log("ERROR " + e.message); process.exit(1); });

