.record-list { margin: 0; padding: 0; list-style: none; }.record-item { display: grid; grid-template-columns: 1fr min(210px, 30%); gap: 10px 24px; padding: 15px 0; border-bottom: 1px solid #263962; }.record-heading { display: flex; justify-content: space-between; align-items: start; gap: 14px; }.record-title { color: #b9ceff; display: block; }.record-date, .record-file, .record-duration { color: #9eacca; font-size: .8rem; }.record-date { margin-top: 3px; display: block; }.record-file { margin: 6px 0 0; }.record-transcript { margin: 7px 0 0; line-height: 1.65; }.record-transcript mark { color: #0d1a35; background: #f5cc65; border-radius: 3px; padding: 0 2px; }
/* The expression reading, set apart from the transcript so the two are not mistaken for each other: one is what was said, the other is a hedged guess about a face. */
.record-cue { margin: 7px 0 0; color: #c3b6ff; font-size: .82rem; }.record-cue:empty { display: none; }
