/* --- layout additions ---------------------------------------------------- */
/* Model access sits above the history search, full width, because a key has to be in place before a query is worth running. */
.llm-card, .archive-card { grid-column: 1 / -1; }
/* The two status cards at the top were the tallest things on the page while carrying the least: heading margin, card padding and the transcript box are all trimmed so the history list starts above the fold. */
.compact { padding: 18px 20px; }.section-heading.tight { margin-bottom: 14px; }.compact .live-transcript { min-height: 92px; margin: 12px 0; padding: 14px; }.compact .volume-box.flush { border-top: 0; padding-top: 4px; margin-top: 4px; }.compact .actions { margin-top: 14px; }.compact .status { min-height: 0; margin-top: 12px; }.compact input[type="range"] { margin: 12px 0 4px; }.compact textarea { min-height: 54px; }
/* Collapsible demo tools: closed they cost one line instead of a third of the card. */
details.simulator { border-top: 1px solid #30436f; padding-top: 12px; margin-top: 14px; }details.simulator > summary { cursor: pointer; color: #9db7ff; font-size: .78rem; font-weight: 700; list-style: none; }details.simulator > summary::-webkit-details-marker { display: none; }details.simulator > summary::before { content: "▸ "; }details.simulator[open] > summary::before { content: "▾ "; }details.simulator > summary:hover { color: #b9ceff; }
/* The key panel's own form needs the key field to be the wide one. */
.llm-form { grid-template-columns: minmax(150px, .8fr) minmax(120px, .6fr) minmax(200px, 1.4fr) auto; }
.fineprint { margin-top: 10px; font-size: .8rem; color: #93a2c4; }.fineprint code, .hint code { background: rgb(9 15 34 / 70%); border: 1px solid #30436f; border-radius: 4px; padding: 0 4px; font-size: .95em; }
.demo-badge.ok { color: #6ee7b7; border-color: #2f8f6b; background: rgb(46 143 107 / 18%); }
@media (max-width: 840px) { .llm-form { grid-template-columns: 1fr 1fr; } }
@media (max-width: 760px) { .llm-card { grid-column: auto; }.llm-form { grid-template-columns: 1fr; }.record-item { grid-template-columns: 1fr; }.record-player { width: 100%; } }

