// MiMo issues two kinds of credential and they do not share an endpoint. Using
// the wrong one answers 401 Invalid API Key, which reads as a bad key and sends
// people looking in the wrong place -- so the host follows the prefix instead of
// being left to whoever fills the form.
const LLM_HOSTS = {
  "sk-": "api.xiaomimimo.com",
  "tp-": "token-plan-cn.xiaomimimo.com"
};

function hostForKey(key) {
  for (const [prefix, host] of Object.entries(LLM_HOSTS)) {
    if (key.startsWith(prefix)) return host;
  }
  return null;
}

function showLlmConfig(config) {
  if (!config || config.configured !== true) {
    llmStatus.textContent = "开发板上还没有配置模型。";
    llmStatus.className = "status";
    llmBadge.textContent = "未配置";
    llmBadge.className = "demo-badge";
    return;
  }
  // The board returns four characters and a length, never the key. Displaying
  // a credential in full would put it in every screenshot of this page.
  llmStatus.textContent =
    `已配置：${config.host} / ${config.model}，` +
    `key ${config.keyPrefix}…（共 ${config.keyLength} 位）`;
  llmStatus.className = "status success";
  llmBadge.textContent = "已配置";
  llmBadge.className = "demo-badge ok";
  if (config.host) llmHost.value = config.host;
  if (config.model) llmModel.value = config.model;
}

