// Switch the endpoint as soon as the prefix is recognisable, so the mismatch
// is prevented rather than diagnosed later from a 401.
llmKey.addEventListener("input", () => {
  const host = hostForKey(llmKey.value.trim());
  if (host && llmHost.value !== host) {
    llmHost.value = host;
    llmStatus.textContent = `已按 key 前缀切换端点为 ${host}。`;
    llmStatus.className = "status";
  }
});

llmForm.addEventListener("submit", async (event) => {
  event.preventDefault();
  const key = llmKey.value.trim();
  if (!key) {
    llmStatus.textContent = "请先填入 key。";
    llmStatus.className = "status error";
    return;
  }

  // Warn but do not block: an unrecognised prefix may just be a kind of key
  // this page has not been told about, and refusing it would be worse than
  // saying so.
  const expected = hostForKey(key);
  if (expected && llmHost.value.trim() !== expected) {
    llmStatus.textContent =
      `key 以 ${key.slice(0, 3)} 开头，端点应为 ${expected}，已自动更正。`;
    llmStatus.className = "status";
    llmHost.value = expected;
  }

